      SUBROUTINE SNYDERCC     CONSTRAINS COURANT-SNYDER PARAMETERS FOR BEAMC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM1B.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SVP.CIN'C---------------------------------------------------------------------      LOGICAL         LOGIC      REAL            AS(NPVAR+1), CAD(NPVAR+1), CADS(NPVAR+1)C      IF (.NOT. RECENT) CALL BEAM      J = JCON - 20      K = KCON      JSAVE = J      IF (J .GE. 5 .AND. J .NE. 7 .AND. J .NE. 8) GO TO 500      IF (J .EQ. 1 .OR. J .EQ. 3) THEN        FAC = UBEAM(J+1)/UBEAM(J)      ELSE IF (J .EQ. 2 .OR. J .EQ. 4) THEN        J = J - 1        K = J + 1        FAC = -1.0      ELSE IF (J .EQ. 7 .OR. J .EQ. 8) THEN        IF (J .EQ. 7) J = 1        IF (J .EQ. 8) J = 3        K = J        FAC = UBEAM(J+1)/UBEAM(J)      ENDIF      SICC = SIT(J,K)      KSAVE = K      K = J + 1      SIJJ = SIT(J,J)      SIJK = SIT(J,K)      SIKK = SIT(K,K)      EPSC = SQRT(SIJJ*SIKK - SIJK**2)      IF (J .EQ. 1) THEN        EPSX = EPSC      ELSE        EPSY = EPSC      ENDIF      COC = SICC*FAC/EPSC      IF (JSAVE .GE. 7) COC = SQRT(COC)      IF (NV3 .LT. 1) GO TO 100      CW = 1.0/SD**2      A(1) = DE0 - COC      CALL CLI(LOGIC)      IF (LOGIC) GO TO 500C      IF (NV1 .LT. 1) GO TO 100      K = KSAVE      DO 40 N = 1, NV1      IF (.NOT. R2P) THEN        IF (SVP(N)) THEN          SVJK = SV(J,K,N)          GO TO 30        ELSE          GO TO 40        ENDIF      ENDIF      SVJK = 0.0      IF (SVP(N)) THEN        DO 15 L1 = 1, 6        DO 15 L2 = 1, 6        SVJK = SVJK + RC2(J,L1)*SV(L1,L2,N)*RC2(K,L2)   15   CONTINUE      ENDIFC      IF (R2VP(N)) THEN        DO 25 L1 = 1, 6        DO 25 L2 = 1, 6        SVJK = SVJK + R2V(J,L1,N)*SI(L1,L2)*RC2(K,L2)     1       + RC2(J,L1)*SI(L1,L2)*R2V(K,L2,N)   25   CONTINUE      ENDIF   30 A(N+1) = SVJK*FAC/EPSC      CAD(N+1) = CW*A(N+1)*A(N+1)   40 CONTINUEC      IF (JSAVE .NE. 1 .AND. JSAVE .NE. 3) GO TO 100      IF (NV1 .LT. 1) GO TO 100      IF (.NOT. R2P) GO TO 100      DO 90 N = 1, NV1      SVJJ = 0.0      IF (R2VP(N)) THEN        DO 55 L1 = 1, 6        DO 55 L2 = 1, 6        SVJJ = SVJJ + R2V(J,L1,N)*SI(L1,L2)*R2V(J,L2,N)   55   CONTINUE      ENDIFC      IF (R2VP(N) .AND. SVP(N)) THEN        DO 65 L1 = 1, 6        DO 65 L2 = 1, 6        SVJJ = SVJJ + R2V(J,L1,N)*SV(L1,L2,N)*RC2(J,L2)     1       + RC2(J,L1)*SV(L1,L2,N)*R2V(J,L2,N)   65   CONTINUE      ENDIFC      AS(N+1) = SVJJ*FAC      CADS(N+1) = A(1)*CW*AS(N+1)      IF (CAD(N+1) .LT. CADS(N+1)) THEN        DV = SIGN(SQRT(2.0*A(1)/AS(N+1)),A(N+1))        A(N+1) = A(N+1) + DV*AS(N+1)      ENDIF   90 CONTINUEC  100 CALL GATHER  500 RETURN      END